<?php $isMentors=$kind==='mentors';$total=$isMentors?$mentorTotal:$experienceTotal;$selectedTopic=$_GET['topic']??'';$selectedIssue=$_GET['issue']??'';foreach($terms as $term){if($term['id']===($_GET['term']??'')){if($term['kind']==='topic'){$selectedTopic=$term['id'];}else{$selectedIssue=$term['id'];}}} ?>
<header class="discovery-heading"><?php if(!empty($topicContext)): ?><a class="topic-breadcrumb" href="<?= $this->h($this->url('/topics')) ?>"><?= $this->icon('arrow') ?>همهٔ موضوع‌ها</a><span class="eyebrow"><?= $this->icon($topicContext['icon']) ?>موضوع تجربه</span><h1><?= $this->h($topicContext['title']) ?></h1><p>تجربه‌های منتشرشده در این موضوع را بخوان و با مرشدهای آن آشنا شو.</p><?php else: ?><span class="eyebrow"><?= $this->icon($isMentors?'users':'book') ?><?= $isMentors?'از تجربهٔ دیگران کمک بگیر':'مسیرهای رفته‌شده را بخوان' ?></span><h1><?= $isMentors?'با مرشد آشنا شو':'هر تجربه، آغاز یک گفت‌وگو' ?></h1><p>مسئله‌ات را جست‌وجو کن، تجربه‌های مرتبط را بشناس و با مرشد آشنا شو.</p><a class="topic-breadcrumb" href="<?= $this->h($this->url('/topics')) ?>">مرور همهٔ موضوع‌ها <?= $this->icon('arrow') ?></a><?php endif; ?></header>
<?php if(!empty($topicContext)): ?><nav class="row section" aria-label="مسیر موضوع"><?php foreach($breadcrumbs??[] as $crumb): ?><a href="<?= $this->h($this->url('/topic?id='.$crumb['id'])) ?>"><?= $this->h($crumb['title']) ?></a><span aria-hidden="true">/</span><?php endforeach; ?></nav><?php if($topicContext['description']??''): ?><p class="prose"><?= $this->h($topicContext['description']) ?></p><?php endif; ?><p class="small muted">این فهرست تجربه‌های موضوع و زیرموضوع‌های آن را نشان می‌دهد.</p><?php if(!empty($children)): ?><section class="section"><h2>زیرموضوع‌ها</h2><div class="topics-grid"><?php foreach($children as $topic){require __DIR__.'/topic-card.php';} ?></div></section><?php endif; ?><?php if(!empty($relatedIssues)): ?><section class="section"><h2>مسئله‌های مرتبط</h2><div class="row"><?php foreach($relatedIssues as $i): ?><a class="tag" href="<?= $this->h($this->url('/issue?id='.$i['id'])) ?>"><?= $this->h($i['title']) ?></a><?php endforeach; ?></div></section><?php endif; ?><?php endif; ?>
<div class="discovery-layout"><aside class="discovery-filters"><form method="get" class="card discovery-filter-form"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/<?= $this->h($kind) ?>"><?php endif; ?><div class="filter-heading"><h2><?= $this->icon('topic') ?>جست‌وجو و فیلتر</h2><span class="small muted">به مسئله‌ات نزدیک‌تر شو</span></div><div class="filter-field discovery-filter-query"><label for="search">دنبال چه تجربه‌ای هستی؟</label><input id="search" type="search" name="q" value="<?= $this->h($_GET['q']??'') ?>" maxlength="160" placeholder="موضوع، مسئله یا نام مرشد"></div><div class="filter-field"><label for="topic-filter">موضوع</label><select id="topic-filter" name="topic"><option value="">همهٔ موضوع‌ها</option><?php foreach($terms as $term):if($term['kind']!=='topic'){continue;} ?><option value="<?= $this->h($term['id']) ?>" <?= $selectedTopic===$term['id']?'selected':'' ?>><?= $this->h($term['title']) ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="issue-filter">مسئلهٔ مشترک</label><select id="issue-filter" name="issue"><option value="">همهٔ مسئله‌ها</option><?php foreach($terms as $term):if($term['kind']!=='issue'){continue;} ?><option value="<?= $this->h($term['id']) ?>" <?= $selectedIssue===$term['id']?'selected':'' ?>><?= $this->h($term['title']) ?></option><?php endforeach; ?></select><small class="filter-issue-hint">برای پیدا کردن یک مسئله در حوزه‌های مختلف، موضوع را روی «همه» بگذار.</small></div><div class="filter-field"><label for="sort">مرتب‌سازی</label><select id="sort" name="sort"><option value="relevant" <?= ($_GET['sort']??'relevant')==='relevant'?'selected':'' ?>>مرتبط‌ترین</option><option value="latest" <?= ($_GET['sort']??'')==='latest'?'selected':'' ?>>تازه‌ترین</option></select></div><?php if(!$isMentors): ?><details class="discovery-more" <?= !empty($_GET['target_audience'])||!empty($_GET['constraints'])||!empty($_GET['outcome'])?'open':'' ?>><summary>فیلترهای بیشتر</summary><div class="filter-field"><label for="audience">گروه هدف</label><input id="audience" name="target_audience" value="<?= $this->h($_GET['target_audience']??'') ?>" placeholder="مثلاً مدیران فرهنگی"></div><div class="filter-field"><label for="constraints">شرایط و محدودیت مشابه</label><input id="constraints" name="constraints" value="<?= $this->h($_GET['constraints']??'') ?>"></div><div class="filter-field"><label for="outcome">نوع نتیجه</label><select id="outcome" name="outcome"><option value="">همه نتایج</option><?php foreach(['success'=>'موفق','failure'=>'ناموفق','mixed'=>'ترکیبی','unknown'=>'نامشخص'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($_GET['outcome']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div></details><?php endif; ?><div class="discovery-filter-actions"><button class="primary"><?= $this->icon('eye') ?>جست‌وجو</button><a href="<?= $this->h($this->url('/'.$kind)) ?>">پاک کردن فیلترها</a></div></form></aside>
<section class="discovery-results" aria-label="نتایج جست‌وجو"><div class="results-heading"><h2><?= $isMentors?'مرشدها':'تجربه‌های مرتبط' ?></h2><span><?= (int)$total ?> نتیجه</span></div><div class="discovery-grid"><?php foreach(array_slice($rows,0,20) as $searchIndex=>$row){$searchResultPosition=(max(1,(int)($_GET['page']??1))-1)*20+$searchIndex+1;require __DIR__.($isMentors?'/mentor-card.php':'/experience-card.php');}unset($searchResultPosition); ?></div><?php if(!$rows): ?><div class="discovery-empty"><?= $this->icon($isMentors?'users':'book') ?><h2>هنوز نتیجه‌ای پیدا نشد</h2><p>عبارت کوتاه‌تری بنویس یا یکی از فیلترها را تغییر بده.</p><a class="secondary" href="<?= $this->h($this->url('/'.$kind)) ?>">دیدن همهٔ <?= $isMentors?'مرشدها':'تجربه‌ها' ?></a></div><?php endif; ?><nav class="row section" aria-label="صفحه‌بندی نتایج"><?php $p=max(1,(int)($_GET['page']??1));$filters=http_build_query(['q'=>$_GET['q']??'','topic'=>$selectedTopic,'issue'=>$selectedIssue,'target_audience'=>$_GET['target_audience']??'','constraints'=>$_GET['constraints']??'','outcome'=>$_GET['outcome']??'','sort'=>$_GET['sort']??'relevant']);if($p>1): ?><a class="secondary" href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p-1))) ?>">صفحه قبل</a><?php endif;if(count($rows)>20): ?><a class="secondary" href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p+1))) ?>">صفحه بعد</a><?php endif; ?></nav></section></div>
